import React, { useEffect, useRef, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import songsData from './data/songs';

function SongDetailPage() {
  const { songId } = useParams();
  const navigate = useNavigate();
  const [song, setSong] = useState(null);
  const audioRef = useRef(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState(1);

  useEffect(() => {
    const foundSong = songsData.find((s) => s.id === parseInt(songId));
    if (foundSong) {
      setSong(foundSong);
    } else {
      navigate('/');
    }
  }, [songId, navigate]);

  useEffect(() => {
    if (isPlaying) {
      audioRef.current.play();
    } else {
      audioRef.current.pause();
    }
  }, [isPlaying, song]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = volume;
    }
  }, [volume]);

  const togglePlay = () => {
    setIsPlaying(!isPlaying);
  };

  const handleVolumeChange = (e) => {
    setVolume(parseFloat(e.target.value));
  };

  const handleNext = () => {
    const currentIndex = songsData.findIndex((s) => s.id === song.id);
    const nextIndex = (currentIndex + 1) % songsData.length;
    navigate(`/song/${songsData[nextIndex].id}`);
  };

  const handlePrev = () => {
    const currentIndex = songsData.findIndex((s) => s.id === song.id);
    const prevIndex = (currentIndex - 1 + songsData.length) % songsData.length;
    navigate(`/song/${songsData[prevIndex].id}`);
  };

  if (!song) return null;

  return (
    <div className="song-detail-page">
      <img src={song.cover} alt={song.album} className="detail-cover-large" />
      <div className="detail-info">
        <h1>{song.title}</h1>
        <h2>{song.artist}</h2>
        <p>Album: {song.album}</p>
        <p>Duration: {song.duration}</p>
      </div>
      <audio ref={audioRef} src={song.audioSrc} />
      <div className="detail-controls">
        <button onClick={handlePrev} aria-label="Previous">&#9664;&#9664;</button>
        <button onClick={togglePlay} aria-label={isPlaying ? 'Pause' : 'Play'}>
          {isPlaying ? '❚❚' : '▶'}
        </button>
        <button onClick={handleNext} aria-label="Next">&#9654;&#9654;</button>
        <input
          type="range"
          min="0"
          max="1"
          step="0.01"
          value={volume}
          onChange={handleVolumeChange}
          className="volume-control"
          aria-label="Volume"
        />
      </div>
    </div>
  );
}

export default SongDetailPage;
